# Step 2.
# Generate (long text, extraction output) datasets.
# 
# Combine texts and entities into longer examples,
# and replace old delimiters with the new format.
# 
# Depend on the datasets generated by `generate_text_entites_dataset.py`.

import json
import re
from transformers import AutoTokenizer
from prompt import PROMPTS

# --- Configuration ---
MODEL_NAME = "Qwen3-0.6B"
LOCAL_MODEL_PATH = f"Y:/Models/{MODEL_NAME}"
TARGET_TOKEN_COUNT = 600
INPUT_FILES = {
    "train": "./text_entities_dataset/text_to_correct_train.json",
    "dev": "./text_entities_dataset/text_to_correct_dev.json",
}
OUTPUT_FILES = {
    "train": f"./long_text_dataset/text_to_correct_{TARGET_TOKEN_COUNT}_train.json",
    "dev": f"./long_text_dataset/text_to_correct_{TARGET_TOKEN_COUNT}_dev.json",
}

# --- Delimiters for parsing ---
TUPLE_DELIMITER = PROMPTS["NEW_DEFAULT_TUPLE_DELIMITER"]
RECORD_DELIMITER = PROMPTS["DEFAULT_RECORD_DELIMITER"]  # Keep for parsing, but output will use \n
COMPLETION_DELIMITER = PROMPTS["DEFAULT_COMPLETION_DELIMITER"]

def combine_examples(input_path: str, output_path: str, tokenizer):
    """
    Reads a JSON file with short examples, combines them into longer examples
    based on a target token count, and saves them to a new JSON file.
    """
    try:
        with open(input_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error reading {input_path}: {e}")
        return

    combined_examples = []
    
    current_long_sentence = ""
    current_entity_parts = []
    current_relationship_parts = []
    current_keywords = set()

    token_count_total = 0

    def finalize_and_reset():
        nonlocal current_long_sentence, current_entity_parts, current_relationship_parts, current_keywords
        if not current_long_sentence:
            return

        # 1. Join all entity and relation records in the correct order, using NEW tuple delimiter and \n as record delimiter
        all_parts = current_entity_parts + current_relationship_parts
        long_response_str = "\n".join(all_parts)

        # 2. Add the final completion delimiter
        long_response_str += COMPLETION_DELIMITER

        # 3. Add the complete example to our list
        combined_examples.append({
            "sentence": current_long_sentence.strip(),
            "response": long_response_str
        })

        # 4. Reset for the next long example
        current_long_sentence = ""
        current_entity_parts = []
        current_relationship_parts = []
        current_keywords = set()

    for example in data:
        sentence = example["sentence"]
        response = example["response"]

        # Check if adding the new sentence would exceed the token limit
        potential_sentence = current_long_sentence + " " + sentence
        token_count = len(tokenizer.encode(potential_sentence))

        if current_long_sentence and token_count > TARGET_TOKEN_COUNT:
            token_count_total += token_count
            finalize_and_reset()

        # Add current example's data to the buffers
        current_long_sentence += " " + sentence
        
        # Parse the response to separate keywords from other records
        response_content = response.removesuffix(COMPLETION_DELIMITER).strip()
        records = re.split(rf'\s*{re.escape(RECORD_DELIMITER)}\s*', response_content)

        for record in records:
            record = record.strip()
            if not record:
                continue

            # Remove all quotation marks for output
            record_no_quotes = record.replace('"', '')

            # Entity: just remove quotes and replace tuple delimiter
            if record.startswith('("entity"') or record.startswith('(entity'):
                # Remove quotes, replace tuple delimiter, remove parentheses
                rec = re.sub(re.escape(PROMPTS["DEFAULT_TUPLE_DELIMITER"]), TUPLE_DELIMITER, record_no_quotes)
                rec = rec.strip('()')
                current_entity_parts.append(rec)
            # Relationship: change to 'relation', swap 4th/5th fields, remove last delimiter and digit, remove quotes
            elif record.startswith('("relationship"') or record.startswith('(relationship'):
                # Remove quotes, replace tuple delimiter, remove parentheses
                rec = re.sub(re.escape(PROMPTS["DEFAULT_TUPLE_DELIMITER"]), TUPLE_DELIMITER, record_no_quotes)
                rec = rec.strip('()')
                # Split fields
                fields = rec.split(TUPLE_DELIMITER)
                if len(fields) >= 6:
                    # fields: [relationship, src, tgt, desc, keywords, digit]
                    fields[0] = 'relation'  # change type
                    # Swap 3rd and 4th fields (desc <-> keywords)
                    # New order: relation, src, tgt, keywords, desc
                    new_fields = [fields[0], fields[1], fields[2], fields[4], fields[3]]
                    rec = TUPLE_DELIMITER.join(new_fields)
                    current_relationship_parts.append(rec)
                else:
                    # If not enough fields, skip or append as is (robustness)
                    continue
            # Remove content_keywords
            elif record.startswith('("content_keywords"') or record.startswith('(content_keywords'):
                continue
            else:
                pass # Ignore unknown record types

    # Finalize any remaining example after the loop finishes
    finalize_and_reset()

    # Save the new combined examples to the output file
    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(combined_examples, f, indent=2)
        
    print(f"Successfully combined {len(data)} short examples into {len(combined_examples)} long examples in {output_path}")
    print(f"Average token count: {token_count_total / len(combined_examples)}")


def main():
    print("Loading tokenizer...")
    tokenizer = AutoTokenizer.from_pretrained(LOCAL_MODEL_PATH)
    
    for data_type in ["train", "dev"]:
        input_file = INPUT_FILES[data_type]
        output_file = OUTPUT_FILES[data_type]
        print(f"\nProcessing {input_file}...")
        combine_examples(input_file, output_file, tokenizer)

if __name__ == "__main__":
    main()
